<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sudoku</title>
    <style>
        body {
            font-family: Arial, sans-serif;
        }
        #sudoku {
            width: 400px;
            height: 400px;
            border: 1px solid #ccc;
            margin: 40px auto;
            text-align: center;
        }
        .error {
            border-bottom: 2px solid #ccc;
            padding-bottom: 5px;
            background-color: #f9f9f9;
        }
        .correct {
            border-bottom: 2px solid #ccc;
            padding-bottom: 5px;
            background-color: #b3b3b3;
        }
        #reset {
            background-color: #4CAF50;
            color: #fff;
            padding: 10px 20px;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }
        #reset:hover {
            background-color: #3e8e41;
        }
    </style>
</head>
<body>
    <div id="sudoku">
        <div class="error" id="error"></div>
        <div class="correct" id="correct"></div>
        <div id="solution"></div>
        <input type="text" id="cella" readonly>
        <button id="reset">Reset</button>
        <p id="message"></p>
    </div>

    <script>
        let rows = 9;
        let cols = 9;
        let cellas = Array(9).fill(null).map(() => Array(9).fill(null));
        let solution = Array(9).fill(null);
        let error = Array(9).fill(null).map(() => Array(9).fill(null));
        let correct = Array(9).fill(null).map(() => Array(9).fill(null));

        const sudoku = () => {
            let row = Math.floor(Math.random() * rows);
            let col = Math.floor(Math.random() * cols);
            let cella = Math.floor(Math.random() * rows) * cols + col;
            let cellaValue = cella === row * cols + col ? cella : 0;

            cellas[row][col] = cellaValue;
            solution[row] = cellaValue;
            correct[row][col] = 1;
        };

        const isComplete = () => {
            for (let i = 0; i < rows; i++) {
                for (let j = 0; j < cols; j++) {
                    if (cellas[i][j] === 0) return false;
                }
            }
            return true;
        };

        const getCellValue = (row, col) => {
            if (correct[row][col] !== 1) return 0;
            return solution[row][col];
        };

        const getPossibleValues = (row, col) => {
            let possibleValues = [];
            if (row === 0 || row === rows - 1) {
                possibleValues.push(1);
                possibleValues.push(2);
                possibleValues.push(3);
                possibleValues.push(4);
                possibleValues.push(5);
                possibleValues.push(6);
                possibleValues.push(7);
                possibleValues.push(8);
            } else {
                possibleValues.push(1);
                possibleValues.push(2);
                possibleValues.push(3);
                possibleValues.push(4);
                for (let i = 0; i < 9; i++) {
                    if (correct[row - 1][i] === 1) possibleValues.push(i + 1);
                    if (correct[row][i - 1] === 1) possibleValues.push(i + 1);
                }
                possibleValues.push(9);
            }

            if (col === 0 || col === cols - 1) {
                possibleValues.push(1);
                possibleValues.push(2);
                possibleValues.push(3);
                possibleValues.push(4);
                possibleValues.push(5);
                possibleValues.push(6);
                possibleValues.push(7);
                possibleValues.push(8);
            } else {
                possibleValues.push(1);
                possibleValues.push(2);
                possibleValues.push(3);
                possibleValues.push(4);
                for (let i = 0; i < 9; i++) {
                    if (correct[i][row - 1] === 1) possibleValues.push(i + 1);
                    if (correct[i][col - 1] === 1) possibleValues.push(i + 1);
                }
                possibleValues.push(9);
            }
            return possibleValues;
        };

        const handleCellClick = (row, col) => {
            if (error[row][col] !== 0) {
                alert(`Errore nella cella ${row},${col}`);
                return;
            }
            const value = document.getElementById("cella").value;
            if (value === "") return;

            if (correct[row][col] === 1) {
                alert("La cella è già completa.");
                return;
            }

            cellas[row][col] = value;
            solution[row] = value;
            correct[row][col] = 1;

            document.getElementById("error").innerHTML = "";
            document.getElementById("correct").innerHTML = "";
            document.getElementById("solution").innerHTML = "";
            document.getElementById("message").innerHTML = "";

            if (isComplete()) {
                sudoku();
                alert("Gioco completato!");
            } else {
                const possibleValues = getPossibleValues(row, col);
                if (possibleValues.length > 0) {
                    alert(possibleValues.join(", "));
                    document.getElementById("cella").value = "";
                    document.getElementById("cella").readonly = true;
                } else {
                    alert("La cella è vuota.");
                }
            }
        };

        const handleReset = () => {
            sudoku();
            document.getElementById("error").innerHTML = "";
            document.getElementById("correct").innerHTML = "";
            document.getElementById("solution").innerHTML = "";
            document.getElementById("message").innerHTML = "";
            document.getElementById("cella").value = "";
            document.getElementById("cella").readonly = true;
        };

        const handleSolution = () => {
            document.getElementById("message").innerHTML = "La soluzione è: \n" + solution.join("\n");
            document.getElementById("cella").readonly = false;
        };

        sudoku();

        document.getElementById("reset").addEventListener("click", handleReset);
        document.getElementById("cella").addEventListener("keyup", handleCellClick);
        document.getElementById("cella").addEventListener("blur", handleSolution);
        document.getElementById("solution").addEventListener("blur", handleSolution);
    </script>
</body>
</html>
